-- a95b95ea | ما أصل علم الميراث؟
UPDATE qa_questions SET
  answer = 'مبناه على أنصبةٍ مقدَّرةٍ بالنصّ لا بالرأي. ففي كتاب الله: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ﴾ [النساء: 11]، وأنصبةُ الزوجين وولد الأمّ: ﴿وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ﴾ [النساء: 12]، وخاتمةُ ذلك في الكلالة: ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ﴾ [النساء: 176]. وفي السنة قولُه صلى الله عليه وسلم: «أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا، فَمَا بَقِيَ فَهْوَ لِأَوْلَى رَجُلٍ ذَكَرٍ» (البخاري ح٦٧٣٢، ومسلم ح١٦١٥) — فما سمّى اللهُ له فرضًا أُعطيه، وما فَضَل فللعصبة. وضبطُ مسائله في الرحبية وشرحها: أسبابُه ثلاثة — «أَسْبَابُ مِيرَاثِ الْوَرَى ثَلاَثهْ ... كلٌّ يُفِيدُ رَبَّهُ الْوِرَاثَهْ»، «وَهْيَ نِكَاحٌ وَوَلاَءٌ وَنَسَبْ ... مَا بَعْدَهُنَّ لِلْمَوَارِيثِ سَبَبْ» (ص١٨)؛ وموانعُه ثلاثة — «رِقٌّ وَقَتْلٌ وَاخْتِلاَفُ دِينِ ... فَافْهَمْ فَلَيْسَ الشَّكُّ كالْيَقِينِ» (ص١٨)؛ والورثةُ محصورون — «وَالْوَارِثُونَ مِنَ الرِّجَالِ عَشَرَهْ ... أَسْمَاؤُهُمْ مَعْرُوفَةٌ مُشْتَهَرهْ» (ص١٩)، «وَالْوَارِثَاتُ مِنَ النِّسَاءِ سَبْعُ ... لَمْ يُعْطِ أُنْثى غَيْرَهُنَّ الْشَّرْعُ» (ص٢١)؛ والفروضُ ستّة — «فَالْفَرْضُ في نَصِّ الْكِتَابِ سِتَّهْ ... لاَ فَرْضَ في الإِرْثِ سِوَاهَا الْبَتَّهْ» (ص٢٢)، وحدُّ الفرض: «نصيبٌ مقدَّرٌ شَرعاً، لا يزِيدُ إلا بالرَّدِّ، ولا ينقُصُ إلا بالعَوْل» (ص٢٢). ثم الحجبُ، وهو «من أعظم أبواب الفرائض وأهمها، وهو قسمان»: «حجب حرمان: ويدخل على جميعِ الورثة إلا الأولادِ والأبوين والزوجين»، «وحجب نقصان: ويدخُلُ على جميعِهم» (ص٣٤).',
  reference = 'القرآن الكريم (النساء: ١١ و١٢ و١٧٦)؛ صحيح البخاري (ط السلطانية): ح٦٧٣٢، ج٨/ص١٥٠ (باب ميراث الولد من أبيه وأمه)؛ صحيح مسلم (ت محمد فؤاد عبد الباقي): ح١٦١٥، ج٣/ص١٢٣٣؛ السبيكة الذهبية على المنظومة الرحبية لفيصل بن عبد العزيز آل مبارك (اعتنى به محمد بن حسن بن عبد الله آل مبارك، دار كنوز إشبيليا بالرياض، ط١ ١٤٢٧هـ، ضمن رسالتان في علم الفرائض): ص١٦ و١٨ و١٩ و٢١ و٢٢ و٣٤ | الكلمات المفتاحية: ميراث، فرائض، ورثة',
  evidence = 'أصلُه نصُّ الكتاب: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ﴾ [النساء: 11]، ﴿وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ﴾ [النساء: 12]، ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ﴾ [النساء: 176]. ثم السنةُ: «أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا، فَمَا بَقِيَ فَهْوَ لِأَوْلَى رَجُلٍ ذَكَرٍ» (البخاري ح٦٧٣٢، ج٨/ص١٥٠؛ ومسلم ح١٦١٥، ج٣/ص١٢٣٣). وعليه بنى الرحبيُّ منظومته: «فَالْفَرْضُ في نَصِّ الْكِتَابِ سِتَّهْ ... لاَ فَرْضَ في الإِرْثِ سِوَاهَا الْبَتَّهْ»، «نِصْفٌ وَرُبْعٌ ثَمَّ نِصْفُ الْرُّبْعِ ... وَالْثُّلْثُ وَالْسُّدْسُ بِنَصِّ الْشَّرْعِ»، «وَالْثُّلُثَانِ وَهُمَا الْتَّمَامُ» (ص٢٢)، وقال شارحُها في آي المواريث: «فلا بُدَّ للطالب من حفظِها؛ لتكونَ لَهُ أصلاً يَرجِعُ إليه» (ص١٦).',
  verification_status = 'verified'
WHERE id = 'a95b95ea-fe51-4c89-b308-b38a5992d2bd'
  AND reference = 'القرآن الكريم؛ الرحبية وشروحها | الكلمات المفتاحية: ميراث، فرائض، ورثة'
  AND evidence = 'آيات المواريث في سورة النساء.'
  AND answer = 'يقوم على أنصبة مقدرة في كتاب الله وسنة رسوله ﷺ، ويحتاج إلى ضبط مسائل الورثة والحجب.';

-- 07af54bb | كم عدد الصلوات المفروضة يوميًا وليليًا؟
UPDATE qa_questions SET
  answer = 'خمسُ صلواتٍ في اليوم والليلة: الفجرُ والظهرُ والعصرُ والمغربُ والعشاء. والعددُ منصوصٌ لا مستفادٌ من العمل وحدَه؛ قال صلى الله عليه وسلم لسائله عن الإسلام: «خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ»، فسأله: «هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ» (البخاري ح٤٦، ومسلم ح١١) — ففيه حصرُ المفروض في الخمس وأن ما عداها تطوُّع. وأصلُ فرضها ليلةَ الإسراء خمسين ثم خُفِّفت مع بقاء أجرها: «فَفَرَضَ اللهُ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً»، ثم «هِيَ خَمْسٌ وَهِيَ خَمْسُونَ، لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ» (البخاري ح٣٤٩، ومسلم ح١٦٣). وأسماؤها مسرودةٌ بمواقيتها في حديث عبد الله بن عمرو: الظهرُ «إِذَا زَالَتِ الشَّمْسُ»، والعصرُ «مَا لَمْ تَصْفَرَّ الشَّمْسُ»، والمغربُ «مَا لَمْ يَغِبْ الشَّفَقُ»، والعشاءُ «إِلَى نِصْفِ اللَّيْلِ الأَوْسَطِ»، والصبحُ «مِنْ طُلُوعِ الْفَجْرِ. مَا لَمْ تَطْلُعِ الشَّمْسُ» (مسلم ح٦١٢).',
  reference = 'صحيح البخاري (ط السلطانية): ح٤٦، ج١/ص١٨ (باب الزكاة من الإسلام)، وح٣٤٩، ج١/ص٧٩ (باب كيف فرضت الصلاة في الإسراء)؛ صحيح مسلم (ت محمد فؤاد عبد الباقي): ح١١، ج١/ص٤١، وح١٦٣، ج١/ص١٤٩، وح٦١٢، ج١/ص٤٢٧ (باب أوقات الصلوات الخمس) | الكلمات المفتاحية: الصلوات الخمس، فرض الصلاة',
  evidence = 'العددُ منصوصٌ في الصحيحين لا مأخوذٌ من العمل وحدَه: سأل الأعرابيُّ عن الإسلام فقال رسول الله صلى الله عليه وسلم: «خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ. فَقَالَ: هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ» (البخاري ح٤٦، ج١/ص١٨؛ ومسلم ح١١، ج١/ص٤١). وأصلُ فرضها ليلةَ الإسراء: «فَفَرَضَ اللهُ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً»، ثم قال ربُّه: «هِيَ خَمْسٌ وَهِيَ خَمْسُونَ، لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ» (البخاري ح٣٤٩، ج١/ص٧٩؛ ومسلم ح١٦٣، ج١/ص١٤٩). وأسماؤها بمواقيتها: «وَقْتُ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ ... وَوَقْتُ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ. وَوَقْتُ صَلَاةِ الْمَغْرِبِ مَا لَمْ يَغِبْ الشَّفَقُ. وَوَقْتُ صَلَاةِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ الأَوْسَطِ. وَوَقْتُ صَلَاةِ الصُّبْحِ مِنْ طُلُوعِ الْفَجْرِ» (مسلم ح٦١٢، ج١/ص٤٢٧).',
  verification_status = 'verified'
WHERE id = '07af54bb-43a3-4bb7-8a9d-ef83fc51d116'
  AND reference = 'السنة النبوية المتواترة عملاً | الكلمات المفتاحية: الصلوات الخمس، فرض الصلاة'
  AND evidence = 'فُرضت الصلوات الخمس ليلة الإسراء والمعراج، وثبت عددها بالتواتر العملي المتصل بين المسلمين جيلاً بعد جيل.'
  AND answer = 'خمس صلوات: الفجر والظهر والعصر والمغرب والعشاء.';

-- b31fc308 | من الذين لا تصح وصيتهم شرعًا؟
UPDATE qa_questions SET
  answer = 'لا تصحّ الوصية ممن لا قصدَ له معتبَرًا شرعًا، وهم عند البهوتي: «(مِنْ سَكْرَان أَوْ مَجْنُونٍ) مُطْبَقٍ (وَمُبَرْسَمٍ وَطِفْلٍ دُونَ التَّمْيِيزِ) لِأَنَّهُ لَا حُكْمَ لِكَلَامِهِمْ» (كشاف القناع، ج٤/ص٣٣٦)، وقال ابن قدامة: «ولا تَصِحُّ وَصِيَّةُ المجْنونِ، ولا تَدْبِيرُه؛ لأَنَّه لا يَصِحُّ شىءٌ من تَصَرُّفاتِه»، وقيَّده بحال الإفاقة: «وإن كان يُجَنُّ يومًا، ويُفِيقُ يومًا، صَحَّ تَدْبِيرُه فى إفاقَتِه» (المغني، ج١٤/ص٤٣٥). وأصلُ ذلك رفعُ القلم: «رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ المُبْتَلَى حَتَّى يَبْرَأَ، وَعَنِ الصَّبِيِّ حَتَّى يَكْبُرَ» (أبو داود ح٤٣٩٨). وأما الصبيُّ المميِّز فوصيتُه صحيحةٌ عندهم: «وَتَصِحُّ الْوَصِيَّةُ (مِنْ مُمَيِّزٍ عَاقِلٍ)» (كشاف القناع، ج٤/ص٣٣٦)، «وجملتُه أَنَّ تَدْبِيرَ الصَّبِىِّ المُمَيِّزِ، ووَصِيّتَه، جائزةٌ» — وليست محلَّ اتفاق: «وهو إحْدَى الرِّوايتَيْنِ عن مالكٍ، وأحدُ قَوْلَىِ الشَّافِعىِّ»، «وقال الحسنُ، وأبو حنيفةَ: لا يَصِحُّ تَدْبِيرُه، كالمَجْنُونِ» (المغني، ج١٤/ص٤٣٤). وأما المكرَهُ فلم يُعدّ في شروط الموصي في هذين الموضعين، وحكمُه راجعٌ إلى قاعدة الإكراه العامّة في التصرفات: «الْإِكْرَاهُ يُسْقِطُ أَثَرَ التَّصَرُّفِ عِنْدَنَا، إلَّا فِي خَمْسَةِ مَوَاضِعَ» (الغزالي في البسيط، نقله السيوطي في الأشباه والنظائر، ص٢٠٣).',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي (راجعه هلال مصيلحي، مكتبة النصر الحديثة بالرياض): ج٤/ص٣٣٦ (كتاب الوصايا)؛ المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب): ج١٤/ص٤٣٤-٤٣٥ (مسألة ١٩٧٦)؛ سنن أبي داود (ت محمد محيي الدين عبد الحميد): ح٤٣٩٨، ج٤/ص١٤٠؛ الأشباه والنظائر للسيوطي (دار الكتب العلمية ببيروت، ط١ ١٤٠٣هـ/١٩٨٣م): ص٢٠٣ (فصل في تكليف المكره) | الكلمات المفتاحية: الوصية، الأهلية، شروط الموصي',
  evidence = 'حدَّ البهوتي أهليةَ الموصي فقال: «وَتَصِحُّ الْوَصِيَّةُ (مِنْ مُمَيِّزٍ عَاقِلٍ) لِلْوَصِيَّةِ لِأَنَّهَا تَصَرُّفٌ تَمَحَّضَ نَفْعًا لَهُ»، «وَ (لَا) تَصِحُّ الْوَصِيَّةُ (مِنْ سَكْرَان أَوْ مَجْنُونٍ) مُطْبَقٍ (وَمُبَرْسَمٍ وَطِفْلٍ دُونَ التَّمْيِيزِ) لِأَنَّهُ لَا حُكْمَ لِكَلَامِهِمْ» (كشاف القناع، ج٤/ص٣٣٦). وقال ابن قدامة: «ولا تَصِحُّ وَصِيَّةُ المجْنونِ، ولا تَدْبِيرُه؛ لأَنَّه لا يَصِحُّ شىءٌ من تَصَرُّفاتِه. وإن كان يُجَنُّ يومًا، ويُفِيقُ يومًا، صَحَّ تَدْبِيرُه فى إفاقَتِه» (المغني، ج١٤/ص٤٣٥). وأصلُ رفع التكليف: «رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ المُبْتَلَى حَتَّى يَبْرَأَ، وَعَنِ الصَّبِيِّ حَتَّى يَكْبُرَ» (أبو داود ح٤٣٩٨، ج٤/ص١٤٠). وأما الإكراهُ فلم يُذكر في شروط الموصي في الموضعين، وإنما هو قاعدةٌ عامّةٌ في التصرفات: «قَالَ الْغَزَالِيُّ فِي الْبَسِيطِ: الْإِكْرَاهُ يُسْقِطُ أَثَرَ التَّصَرُّفِ عِنْدَنَا، إلَّا فِي خَمْسَةِ مَوَاضِعَ» (نقله السيوطي في الأشباه والنظائر، ص٢٠٣).',
  verification_status = 'verified'
WHERE id = 'b31fc308-b8e8-4a79-b4eb-566cd5d03573'
  AND reference = 'أبواب أهلية التصرف في كتب الفقه العام | الكلمات المفتاحية: الوصية، الأهلية، شروط الموصي'
  AND evidence = 'قاعدة فقهية عامة مستقرة في أبواب أهلية التصرفات عند الفقهاء'
  AND answer = 'لا تصح وصية الصغير غير المميز، والمجنون، والمكره على الوصية بغير حق، لعدم توفر أهلية القصد والاختيار المعتبرة شرعًا في التصرفات، أما الصبي المميز فتصح وصيته عند بعض الفقهاء فيما فيه نفع محض كالوقف والصدقة.';
